CREATE TABLE students (id BIGSERIAL PRIMARY KEY, full_name TEXT NOT NULL, phone TEXT, hostel TEXT NOT NULL, room TEXT NOT NULL, reputation INTEGER NOT NULL DEFAULT 100, created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE menu_items (id BIGSERIAL PRIMARY KEY, name TEXT NOT NULL, category TEXT NOT NULL, price INTEGER NOT NULL, is_custom BOOLEAN NOT NULL DEFAULT false, is_available BOOLEAN NOT NULL DEFAULT true, standalone_delivery INTEGER NOT NULL DEFAULT 0, sort_order INTEGER NOT NULL DEFAULT 0);
CREATE TABLE orders (id BIGSERIAL PRIMARY KEY, code CHAR(4) NOT NULL UNIQUE, student_id BIGINT NOT NULL REFERENCES students(id), items_json JSONB NOT NULL, portions INTEGER NOT NULL, spaghetti_total INTEGER NOT NULL DEFAULT 0, water_bags INTEGER NOT NULL DEFAULT 0, food_subtotal INTEGER NOT NULL, delivery_fee INTEGER NOT NULL, water_fee INTEGER NOT NULL DEFAULT 0, transfer_fee INTEGER NOT NULL DEFAULT 30, credit_applied INTEGER NOT NULL DEFAULT 0, total_due INTEGER NOT NULL, max_budget INTEGER, actual_food_cost INTEGER, refund_due INTEGER NOT NULL DEFAULT 0, sender_name TEXT NOT NULL, transfer_ref TEXT NOT NULL, transfers_count INTEGER NOT NULL DEFAULT 1, status TEXT NOT NULL DEFAULT 'received', submitted_at TIMESTAMPTZ NOT NULL DEFAULT now(), verified_at TIMESTAMPTZ);
CREATE INDEX idx_orders_status ON orders(status);
CREATE INDEX idx_orders_submitted ON orders(submitted_at);
CREATE TABLE push_subscriptions (id BIGSERIAL PRIMARY KEY, role TEXT NOT NULL DEFAULT 'admin', endpoint TEXT NOT NULL UNIQUE, p256dh TEXT NOT NULL, auth TEXT NOT NULL, created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE delivery_wallet (student_id BIGINT PRIMARY KEY REFERENCES students(id), credit_balance INTEGER NOT NULL DEFAULT 0, updated_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE prepaid_bundles (id BIGSERIAL PRIMARY KEY, student_id BIGINT NOT NULL REFERENCES students(id), credits_total INTEGER NOT NULL, credits_used INTEGER NOT NULL DEFAULT 0, expires_at TIMESTAMPTZ NOT NULL);
CREATE TABLE meal_credits (student_id BIGINT PRIMARY KEY REFERENCES students(id), balance INTEGER NOT NULL DEFAULT 0 CHECK (balance <= 10000), updated_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE wash_bookings (id BIGSERIAL PRIMARY KEY, student_id BIGINT NOT NULL REFERENCES students(id), tops_qty INTEGER NOT NULL DEFAULT 0, bottoms_qty INTEGER NOT NULL DEFAULT 0, transfer_fee INTEGER NOT NULL DEFAULT 30, pickup_date DATE NOT NULL, status TEXT NOT NULL DEFAULT 'received', submitted_at TIMESTAMPTZ NOT NULL DEFAULT now());
